import * as THREE from 'three/webgpu';
import * as tsl from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextNode } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {{imageUrl:string}} assets
 * @property {{position:number[],rotation:number[],scale:number[]}} placement
 * @property {{textContent:Array<{text:string}>}} textContent
 * @property {{atlas:{region:{x:number,y:number,w:number,h:number}}}} atlas
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader:any}} textureLoader
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{primitives:any}} primitives
 */

/**
 * Creates a UI element node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// Root container
	const root = new THREE.Object3D();

	// Apply placement if present
	if (config.placement) {
		const { position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config.placement;
		root.position.set(position[0], position[1], position[2]);
		root.rotation.set(rotation[0], rotation[1], rotation[2]);
		root.scale.set(scale[0], scale[1], scale[2]);
	}

	// ---------- TEXTURED PLANE (SPRITE) ----------
	const tex = ctx.textureLoader.load(config.assets?.imageUrl ?? '');
	tex.wrapS = THREE.ClampToEdgeWrapping;
	tex.wrapT = THREE.ClampToEdgeWrapping;

	// Apply atlas UV region if supplied
	if (config.atlas?.atlas?.region && tex.image) {
		const img = tex.image;
		const texW = img.width;
		const texH = img.height;
		const r = config.atlas.atlas.region;
		tex.offset.set(r.x / texW, r.y / texH);
		tex.repeat.set(r.w / texW, r.h / texH);
	}

	// Geometry – unit plane, later scaled to aspect ratio
	const geometry = new THREE.PlaneGeometry(1, 1);
	const material = new MeshBasicNodeMaterial();
	material.map = tsl.texture(tex);
	const plane = new THREE.Mesh(geometry, material);
	plane.renderOrder = 0;

	// Scale plane to match atlas region aspect ratio
	if (tex.image) {
		const r = config.atlas?.atlas?.region ?? { w: 1, h: 1 };
		const aspect = r.w / r.h;
		plane.scale.set(aspect, 1, 1);
	}

	// Billboard – face the camera each frame
	plane.onBeforeRender = (_, __, camera) => {
		plane.quaternion.copy(camera.quaternion);
	};

	root.add(plane);

	// ---------- TEXT LABEL ----------
	if (config.textContent && config.textContent.length) {
		const txt = config.textContent[0].text ?? '';
		const textNode = createTextNode({
			text: txt,
			fontAtlas: ctx.fontAtlas,
			color: new THREE.Color('#16161d'), // ink
			size: 0.13, // body scale – adjust as needed
			align: 'center',
		});
		// Position text slightly in front of the plane to avoid z‑fighting
		textNode.position.set(0, 0, 0.001);
		root.add(textNode);
	}

	// ---------- PRIMITIVE APPLICATION ----------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives[prim.name];
			if (typeof fn === 'function') {
				fn(root, prim.params);
			}
		}
	}

	// ---------- CLEANUP ----------
	root.userData.handlers = {};

	root.userData.cleanup = () => {
		geometry.dispose();
		material.dispose();
		if (tex) tex.dispose();
		gsap.killTweensOf(root);
		if (typeof root.traverse === 'function') {
			root.traverse((obj) => {
				if (obj.userData && typeof obj.userData.cleanup === 'function') {
					obj.userData.cleanup();
				}
			});
		}
	};

	return root;
}
